entries[19956] = { ["name"] = "Wushoolays Amulett der Geister", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Schamane\nBenötigt Stufe 60\nBenutzen: Erhöht den Schaden Eures Zaubers 'Blitzschlagschild' um 100%. Hält 20 Sek. lang an. (3 Min Abklingzeit)\n\nOrnat des Weissagers (0/5)\nUnversehrte Vision von Voodress\nWushoolays Amulett der Geister\nZandalarianischer Armschienen des Weissagers\nZandalarianischer Gürtel des Weissagers\nZandalarianische Halsberge des Weissagers\n(2) Set : Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\n(3) Set : Verbessert die Gesamtdauer Eures Zaubers 'Frostschock' um 1 Sekunden.\n(5) Set : Erhöht den Radius Eures Zaubers 'Blitzschlag' um 5 Meter." }
entries[19957] = { ["name"] = "Hazza'rahs Amulett der Zerstörung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Hexenmeister\nBenötigt Stufe 60\nBenutzen: Erhöht die Chance auf einen kritischen Treffer Eurer Zerstörungszauber um 10%. Hält 20 Sek. lang an. (3 Min Abklingzeit)\n\nRoben des Besessenen (0/5)\nKezans unaufhaltsame Schmach\nHazza'rahs Amulett der Zerstörung\nZandalarianische Handlappen des Besessenen\nZandalarianischer Mantel des Besessenen\nZandalarianische Robe des Besessenen\n(2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht den Schaden Eures Zaubers 'Verderbnis' um 2%.\n(5) Set : Verringert die Abklingzeit Eures Zaubers 'Todesmantel' um 15%." }
entries[19958] = { ["name"] = "Hazza'rahs Amulett der Heilung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\nBenutzen: Reduziert die Zauberzeit Eurer Zauber 'Große Heilung' um 40% und verringert 15 Sek. lang, die Manakosten Eurer Heilzauber um 5%. (3 Min Abklingzeit)\n\nGewandung des Glaubenshüters (0/5)\nDas allsehende Auge von Zuldazar\nHazza'rahs Amulett der Heilung\nZandalarianische Handlappen des Glaubenshüters\nZandalarianische Bindungen des Glaubenshüters\nZandalarianischer Mantel des Glaubenshüters\n(2) Set : Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 22.\n(3) Set : Erhöht die Reichweite Eurer Zauber 'Göttliche Pein' und 'Heiliges Feuer' um 5 Meter.\n(5) Set : Reduziert die Zauberzeit Eures Zaubers 'Gedankenkontrolle' um 0.5 Sekunden." }
entries[19959] = { ["name"] = "Hazza'rahs Amulett der Magie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Magier\nBenötigt Stufe 60\nBenutzen: Erhöht die Chance auf einen kritischen Treffer mit Euren Arkanzaubern um 5% Â und erhöht zusätzlich 20 Sek. lang den Schaden eines kritischen Treffers mit Arkanzaubern um 50%. (3 Min Abklingzeit)\n\nRoben des Illusionisten (0/5)\nJuwel von Kajaro\nHazza'rahs Amulett der Magie\nZandalarianische Handlappen des Illusionisten\nZandalarianischer Mantel des Illusionisten\nZandalarianische Robe des Illusionisten\n(2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Verringert die Manakosten Eurer Zauber 'Arkane Intelligenz' und 'Arkane Brillanz' um 5%.\n(5) Set : Reduziert die Zauberzeit Eures Zaubers 'Flammenstoß' um 0.5 Sekunden." }
