entries[20034] = { ["name"] = "Zandalarianische Robe des Illusionisten", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n100 Rüstung\n+23 Ausdauer\n+24 Intelligenz\nHaltbarkeit 100 / 100\nKlassen: Magier\nAnlegen: Erhöht Eure Chance mit Zaubern zu treffen um 1%.\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 27.\n\nRoben des Illusionisten (0/5)\nJuwel von Kajaro\nHazza'rahs Amulett der Magie\nZandalarianische Handlappen des Illusionisten\nZandalarianischer Mantel des Illusionisten\nZandalarianische Robe des Illusionisten\n(2) Set : Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 12.\n(3) Set : Verringert die Manakosten Eurer Zauber 'Arkane Intelligenz' und 'Arkane Brillanz' um 5%.\n(5) Set : Reduziert die Zauberzeit Eures Zaubers 'Flammenstoß' um 0.5 Sekunden." }
entries[20035] = { ["name"] = "Gletscherstachel", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n31 - 59 Schaden Tempo 1.30\n(34.62 Schaden pro Sekunde)\n+4 Intelligenz\nHaltbarkeit 65 / 65\nAnlegen: Eure Frostblitzzauber haben eine Chance von 6%, dass sie 50 Mana regenerieren.\n\"Teuflische Runen zieren die Klinge.\"" }
entries[20036] = { ["name"] = "Feuerrubin", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nBenutzen: Erhöht den Schaden Eures nächsten Feuerzaubers um bis zu 100 und stellt 1 bis 500 Mana wieder her. Effekt hält 1 Min. lang an. (3 Min Abklingzeit)\n\"Unberechenbarkeit führt zu beidem, Sieg und Tod.\"" }
