entries[20075] = { ["name"] = "Rezept: Schwerer Krokiliskeneintopf", ["text"] = "Benötigt Kochkunst (150)\nBenutzen: Lehrt Euch, wie man einen schweren Krokiliskeneintopf zubereitet.\nSchwerer Krokiliskeneintopf\nBenötigt Stufe 20\nBenutzen: Stellt im Verlauf von 27 Sek. 874.8 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 8 Punkt(e) Ausdauer und Willenskraft.\nBenötigt Zartes Krokiliskenfleisch (2), Feine Gewürze" }
entries[20076] = { ["name"] = "Zandalarianisches Siegel des Mojo", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft eine um bis zu 18 erhöhte Schadens- und Heilwirkung durch Zauber und magische Effekte hinzu." }
