entries[20079] = { ["name"] = "Zanzas Geist", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Erhöht Â 2 Stunden lang die Willenskraft des Spielers um 50 und die Ausdauer um 50. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein. (3 Sek. Abklingzeit)\n\"Gesegnet mit Zanzas Mojo!\"" }
